void main() {
  test('b128 exported mock classes', () {
    expect(_truth['exports'], <dynamic>[
      'MockContextKeyService',
      'MockKeybindingService',
      'MockScopableContextKeyService',
    ]);
    expect(mock.MockContextKeyService().runtimeType.toString(),
        'MockContextKeyService');
    expect(mock.MockKeybindingService().runtimeType.toString(),
        'MockKeybindingService');
    expect(mock.MockScopableContextKeyService().runtimeType.toString(),
        'MockScopableContextKeyService');
  });

  test('b128 MockContextKeyService key lifecycle and no-op boundaries', () {
    final e = _section('contextKeyService');
    final s = mock.MockContextKeyService();
    final withDefault = s.createKey<int>('withDefault', 5);
    final without = s.createKey<int>('without', null);

    _expectDeep(withDefault.get_(), e['initial'], 'initial');
    withDefault.set(7);
    _expectDeep(withDefault.get_(), e['afterSet'], 'afterSet');
    withDefault.reset();
    _expectDeep(withDefault.get_(), e['afterReset'], 'afterReset');
    _expectDeep(without.get_(), e['noDefault'], 'noDefault');
    _expectDeep(s.getContextKeyValue<int>('withDefault'), e['knownValue'],
        'knownValue');
    _expectDeep(s.getContextKeyValue<int>('missing'), e['unknownValue'],
        'unknownValue');
    expect(s.contextMatchesRules(null), e['contextMatches']);
    expect(identical(s.onDidChangeContext, events.eventNone),
        e['onDidChangeIsNone']);

    final seen = <String>[];
    s.bufferChangeEvents(() => seen.add('ran'));
    _expectDeep(seen, e['events'], 'events');
    expect(seen.length, e['buffered']);

    _expectDeep(s.getContext(_FakeTarget()), e['context'], 'context');
    expect(identical(s.createScoped(_FakeTarget()), s), e['scopedIdentity']);
    expect(identical(s.createOverlay(const <List<Object?>>[]), s),
        e['overlayIdentity']);
    s.updateParent(s);
    expect(_norm(e['updateParentReturns']), isNull);
    s.dispose();
    expect(_norm(e['disposeReturns']), isNull);
  });

  test('b128 MockScopableContextKeyService creates fresh scoped instances', () {
    final e = _section('scopable');
    final s = mock.MockScopableContextKeyService();
    final scoped = s.createScoped(_FakeTarget());
    expect(scoped.runtimeType.toString(), e['constructor']);
    expect(scoped != s, e['fresh']);
    expect(scoped.createScoped(_FakeTarget()) != scoped, e['nested']);
  });

  test('b128 MockKeybindingService defaults and USLayout delegation', () {
    final e = _section('keybindingService');
    final s = mock.MockKeybindingService();
    final keyboard = _FakeKeyboard(
        (e['chords'] as List<dynamic>).first as Map<String, Object?>);

    expect(s.inChordMode, e['inChordMode']);
    expect(identical(s.onDidUpdateKeybindings, events.eventNone),
        e['onDidUpdateIsNone']);
    expect(s.getDefaultKeybindingsContent(), e['defaultContent']);
    expect(s.getDefaultKeybindings().length, e['defaults']);
    expect(s.getKeybindings().length, e['keybindings']);
    expect(s.resolveUserBinding('cmd+a').length, e['resolveUserBinding']);
    expect(s.lookupKeybindings('x').length, e['lookupKeybindings']);
    _expectDeep(s.lookupKeybinding('x'), e['lookupKeybinding'],
        'lookupKeybinding');
    expect(s.customKeybindingsCount(), e['customKeybindingsCount']);
    expect(identical(s.softDispatch(keyboard, _FakeTarget()),
        resolver.NoMatchingKb), e['softDispatchIsNoMatching']);
    expect(s.dispatchEvent(keyboard, _FakeTarget()), e['dispatchEvent']);
    s.dispatchByUserSettingsLabel('x', _FakeTarget());
    expect(_norm(e['dispatchByUserSettingsLabel']), isNull);
    _expectDeep(s.enableKeybindingHoldMode('x'),
        e['enableKeybindingHoldMode'], 'enableKeybindingHoldMode');
    expect(s.mightProducePrintableCharacter(keyboard),
        e['mightProducePrintableCharacter']);
    expect(s.toggleLogging(), e['toggleLogging']);
    expect(identical(s.registerSchemaContribution(_FakeContribution()),
        lifecycle.Disposable.none), e['disposableNone']);
    expect(s.appendKeybinding('Do', 'cmd'), e['append']);

    final firstChord = (e['resolveCalls'] as List<dynamic>).first
        as Map<String, dynamic>;
    final firstChordView =
        (firstChord['chords'] as List<dynamic>).first as Map<String, Object?>;
    final resolved = s.resolveKeybinding(kb.KeyCodeChord(
      firstChordView['ctrlKey'] as bool,
      firstChordView['shiftKey'] as bool,
      firstChordView['altKey'] as bool,
      firstChordView['metaKey'] as bool,
      firstChordView['keyCode'] as int,
    ).toKeybinding());
    expect(resolved, hasLength((e['resolveResult'] as List).length));
    expect(resolved.single, isA<uslayout.USLayoutResolvedKeybinding>());
    expect((resolved.single as uslayout.USLayoutResolvedKeybinding).os,
        platform.OS);

    final viaEvent = s.resolveKeyboardEvent(keyboard);
    expect(viaEvent, isA<uslayout.USLayoutResolvedKeybinding>());
    expect(viaEvent.getDispatchChords(), isNotEmpty);
    expect(
      (viaEvent as uslayout.USLayoutResolvedKeybinding).chords.length,
      ((e['viaEventResult'] as Map<String, dynamic>)['chords'] as List).length,
    );
  });

  test('b128 keyboard event builds KeyCodeChord from modifier flags', () {
    final chordMap = (_truth['keybindingService']['chords'] as List<dynamic>)
        .single as Map<String, Object?>;
    final s = mock.MockKeybindingService();
    s.resolveKeyboardEvent(_FakeKeyboard(chordMap));
    final chord = kb.KeyCodeChord(
      chordMap['ctrlKey'] as bool,
      chordMap['shiftKey'] as bool,
      chordMap['altKey'] as bool,
      chordMap['metaKey'] as bool,
      chordMap['keyCode'] as int,
    );
    _expectDeep(_chordView(chord), chordMap, 'keyboard chord');
  });
